package com.franco.desco.adapter.in.web.delivery;import io.swagger.v3.oas.annotations.media.Schema;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;import java.util.List;
public final class DeliveryRequests{private DeliveryRequests(){}@Schema(name="DeliveryLineRequest")public record Line(@NotNull Integer variedadPaltaId,@NotNull Long condicionComercialId,@NotNull@Positive BigDecimal kilogramos){}@Schema(name="DeliveryCreateRequest")public record Create(@NotNull Long operativoSocioId,@NotNull Long predioId,@NotBlank@Size(max=60)String codigoLote,@NotNull Instant fechaHora,@NotNull@Positive BigDecimal pesoBrutoKg,@NotNull@PositiveOrZero BigDecimal taraKg,@NotNull@PositiveOrZero BigDecimal pesoRechazadoKg,@NotBlank@Size(max=20)String estadoControlCalidad,@Size(max=80)String ticketBalanza,@Size(max=400)String observacion,@NotEmpty List<@Valid Line>detalles){}@Schema(name="DeliveryUpdatePreliminaryRequest")public record UpdatePreliminary(@NotNull@Positive BigDecimal pesoBrutoKg,@NotNull@PositiveOrZero BigDecimal taraKg,@NotNull@PositiveOrZero BigDecimal pesoRechazadoKg,@NotBlank@Size(max=20)String estadoControlCalidad,@Size(max=80)String ticketBalanza,@Size(max=400)String observacion,@NotEmpty List<@Valid Line>detalles){}@Schema(name="DeliveryAnnulRequest")public record Annul(@NotBlank@Size(max=500)String motivo){} }
